from dataclasses import replace

from commander.archidekt import parse_deck
from commander.diff import CardChange, diff_decks
from commander.models import Deck, DeckCard
from commander.render import deck_list_markdown
from conftest import Json

EXPECTED_LIST = """\
# Sample, deck..

- Commander: Magda, Brazen Outlaw
- Bracket (as set on Archidekt): 5
- Cards in deck: 9
- Archidekt: https://archidekt.com/decks/10000001
- Last edited: 2026-10-11T20:56:43.155670Z

<!-- Generated by `cmdr sync`; edits here are overwritten. Put notes in notes.md. -->

## Commander (1)

- 1 Magda, Brazen Outlaw

## Combo Pieces (1)

- 1 Battered Golem

## Stax (1)

- 1 Disruptor Flute

## Land (6)

- 6 Mountain

## Not in deck

### Maybeboard (2)

- 1 High-Speed Hoverbike
- 1 Tempestra, Dame of Games
"""


def test_deck_list_markdown(raw_deck: Json) -> None:
    assert deck_list_markdown(parse_deck(raw_deck)) == EXPECTED_LIST


def with_cards(deck: Deck, *cards: DeckCard) -> Deck:
    return replace(deck, cards=cards)


def card(deck: Deck, name: str) -> DeckCard:
    return next(c for c in deck.cards if c.name == name)


def test_first_sync_lists_every_main_card_as_added(raw_deck: Json) -> None:
    diff = diff_decks(None, parse_deck(raw_deck))
    assert [(c.name, c.new_quantity) for c in diff.added] == [
        ("Battered Golem", 1),
        ("Disruptor Flute", 1),
        ("Magda, Brazen Outlaw", 1),
        ("Mountain", 6),
    ]
    assert diff.removed == ()
    assert diff.old_name is None


def test_identical_decks_have_empty_diff(raw_deck: Json) -> None:
    deck = parse_deck(raw_deck)
    assert diff_decks(deck, deck).is_empty


def test_diff_reports_adds_cuts_and_quantity_changes(raw_deck: Json) -> None:
    old = parse_deck(raw_deck)
    mountain = card(old, "Mountain")
    new = with_cards(
        old,
        card(old, "Magda, Brazen Outlaw"),
        card(old, "Battered Golem"),
        replace(mountain, quantity=5),
        replace(mountain, name="Ancient Tomb", quantity=1, categories=("Land",)),
    )
    diff = diff_decks(old, new)
    assert diff.added == (CardChange("Ancient Tomb", 0, 1),)
    assert diff.removed == (CardChange("Disruptor Flute", 1, 0),)
    assert diff.changed == (CardChange("Mountain", 6, 5),)


def test_maybeboard_moves_are_not_main_deck_changes(raw_deck: Json) -> None:
    old = parse_deck(raw_deck)
    hoverbike = card(old, "High-Speed Hoverbike")
    new = with_cards(old, *(c for c in old.cards if c is not hoverbike))
    assert diff_decks(old, new).is_empty


def test_moving_a_card_into_the_deck_is_an_add(raw_deck: Json) -> None:
    old = parse_deck(raw_deck)
    hoverbike = card(old, "High-Speed Hoverbike")
    promoted = replace(hoverbike, categories=("Vehicle",), in_deck=True)
    new = with_cards(old, *(promoted if c is hoverbike else c for c in old.cards))
    assert diff_decks(old, new).added == (CardChange("High-Speed Hoverbike", 0, 1),)


def test_printing_swap_is_not_a_change(raw_deck: Json) -> None:
    old = parse_deck(raw_deck)
    golem = card(old, "Battered Golem")
    reprint = replace(golem, set_code="mh2", collector_number="999", scryfall_id="other")
    new = with_cards(old, *(reprint if c is golem else c for c in old.cards))
    assert diff_decks(old, new).is_empty


def test_rename_is_reported(raw_deck: Json) -> None:
    old = parse_deck(raw_deck)
    diff = diff_decks(old, replace(old, name="New name"))
    assert diff.old_name == "Sample, deck.."
    assert not diff.is_empty
